//! Utility macros and functions
//!
//! This module provides utility macros and type aliases for working with message handlers.

use std::{future::Future, pin::Pin, sync::Arc};


use crate::{Context, Result};

/// Function pointer type for handler registration functions
///
/// This type represents a function that can register a handler type with the broker.
/// It's automatically generated by the `#[msg_flow]` macro when implementing the `Register` trait.
pub type RegisterFn = fn(Arc<Context>) -> Pin<Box<dyn Future<Output = Result<()>> + Send>>;

/// Macro to create an array of registration functions
///
/// This macro takes a list of handler types and creates an array of their `Register::register`
/// functions, which can be passed to `App::connect` or `App::connect_and_wait`.
///
/// ## Arguments
///
/// * `$handler:ty` - One or more handler types that implement the `Register` trait
///
/// ## Returns
///
/// Returns a reference to an array of `RegisterFn` function pointers.
///
/// ## Example
///
/// ```rust,no_run
/// use message_flow::{registers, App};
///
/// # async fn example() -> Result<(), Box<dyn std::error::Error>> {
/// let app = App::new("localhost:4222".to_string()).await?;
/// app.connect_and_wait(registers!(MyHandler1, MyHandler2)).await?;
/// # Ok(())
/// # }
/// ```
///
/// ## Notes
///
/// - All handler types must implement the `Register` trait (automatically done by `#[msg_flow]`)
/// - The macro accepts a trailing comma for convenience
/// - The returned array reference can be used directly with `App` methods
#[macro_export]
macro_rules! registers {
    ($($handler:ty),* $(,)?) => {
        {
             use message_flow::Register;
            &[
                $(<$handler>::register as message_flow::RegisterFn),*
            ]
        }
    };
}
